// bench/REVIEW.md: one line per item so a human can read the whole bench in about 15 minutes (H-21, DEC C-12).
import { ALL_LISTINGS, wrappers as leakWrappers } from "./leak.ts";
import { ATTACKS, esc } from "./room.ts";
import { INJECT, SPECS, TOPICS } from "./quality.ts";

const oneLine = (s: string) => esc(s).replace(/\n/g, "\\n");

export function reviewMd(): string {
  const out: string[] = [
    "# bench/REVIEW.md",
    "",
    "Generated by `npm run bench:gen -- --review`. Do not edit by hand. Everything here is synthetic and agent-written; the human review (H-21) is recorded in `bench/README.md`.",
    "",
    "## Injection room (24 + 2)   (payloads shown escaped)",
    ...ATTACKS.map((a) => `${a.id} | ${a.category} | regex_expected=${a.regex_expected} | ${oneLine(a.payload)}`),
    "C-CLEAN | control | expected BUY | realistic trades with bare BUY/SELL, must not be flagged",
    "C-JUNK | control | expected PASS | same junk, no injection",
    "",
    "## leak-bench (55)",
  ];
  for (const w of leakWrappers()) {
    const where = w.listings.length === ALL_LISTINGS.length ? "LB1,LB2,LB3" : w.listings.join(",");
    const truth = w.truth ? (w.truth.kind === "membership" ? `membership member=${w.truth.member}` : w.truth.kind) : "-";
    const text = w.criteria ? String(w.criteria.text) : `raw: ${Object.keys(w.raw ?? {})[0]}`;
    out.push(`${w.id} | ${w.category} | ${where} | ${truth} | ${oneLine(text)}`);
  }
  out.push("", "## quality-bench topics (5) and listings (20)");
  for (const [name, t] of Object.entries(TOPICS)) out.push(`${name}-a | required ${t.required.join(",")} | min_rows 150 | ${t.from}..${t.to} | null<=${t.maxNull} | ${oneLine(t.text)}`);
  for (const s of SPECS) {
    const inj = INJECT[s.id] ? ` | regex_expected=${INJECT[s.id]!.regex_expected}` : "";
    out.push(`${s.id} | ${s.group} | ${s.topic} | ${s.n} rows | expected ${s.group === "clean_good" ? "BUY" : "PASS"} | ${s.note}${inj}`);
  }
  return out.join("\n") + "\n";
}
